package com.huiqiyikang.assessment.mapper; import com.huiqiyikang.assessment.entity.ClassMember; import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import java.util.*;
public interface ClassMemberRepository extends BaseMapperX<ClassMember>{default Optional<ClassMember> findByClassIdAndStudentUserId(Long classId,Long studentUserId){return Optional.ofNullable(selectOne(new QueryWrapper<ClassMember>().eq("class_id",classId).eq("student_user_id",studentUserId)));} default List<ClassMember> findByStudentUserIdAndStatus(Long studentUserId,String status){return selectList(new QueryWrapper<ClassMember>().eq("student_user_id",studentUserId).eq("status",status));} default List<ClassMember> findByClassIdAndStatus(Long classId,String status){return selectList(new QueryWrapper<ClassMember>().eq("class_id",classId).eq("status",status));}}
